    HFONT CreateNxLikeDialogFont()
    {
        HDC screenDc = GetDC(NULL);
        const int dpiY = screenDc != NULL ? GetDeviceCaps(screenDc, LOGPIXELSY) : 96;
        if (screenDc != NULL)
        {
            ReleaseDC(NULL, screenDc);
        }

        return CreateFontW(
            -MulDiv(9, dpiY, 72),
            0,
            0,
            0,
            FW_NORMAL,
            FALSE,
            FALSE,
            FALSE,
            DEFAULT_CHARSET,
            OUT_DEFAULT_PRECIS,
            CLIP_DEFAULT_PRECIS,
            DEFAULT_QUALITY,
            DEFAULT_PITCH | FF_DONTCARE,
            L"Microsoft YaHei UI");
    }

